import type { DetachedResource } from '@wildflowerhealthio/fhir-r4-adoption'
import { fhirR4Source } from '@wildflowerhealthio/fhir-r4-source'
import type { SourceDescriptor } from '@wildflowerhealthio/http-extraction-fundamentals'
import { rexallBeWellSource } from '@wildflowerhealthio/rexall-be-well-source'
import { shoppersDrugMartSource } from '@wildflowerhealthio/shoppers-drugmart-source'

/**
 * The registered sources a HAR archive's traffic is recognized and decoded
 * through — each grouping its kinds under a user-facing name and detail
 * (recognition is per-URL against the kinds flattened, never one source
 * claiming the archive). The flat pool routing needs is
 * `SourceDescriptor.poolOf(fhirSources)`, and `mergeSharedResources` finds a
 * response's source by its kind here — both derived on demand, so there is no
 * second copy to keep in sync. Registering another source is one static append
 * here.
 */
const fhirSources: readonly SourceDescriptor.SourceDescriptor<DetachedResource.Type>[] = [
  fhirR4Source,
  rexallBeWellSource,
  shoppersDrugMartSource,
]

export { fhirSources }
